-- Explicit public financial columns; the fixture owns the read-only transaction.
WITH
vtxo_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('vtxo_id', vtxo_id, 'expiry', expiry, 'oor_spent_txid', oor_spent_txid, 'spent_in_round', spent_in_round, 'offboarded_in', offboarded_in, 'vtxo_txid', vtxo_txid, 'exit_delta', exit_delta, 'policy_type', policy_type, 'server_pubkey', server_pubkey, 'amount', amount, 'anchor_point', anchor_point, 'spend_state', spend_state, 'confirmed_height', confirmed_height, 'onchain_spent_height', onchain_spent_height, 'onchain_spent_txid', onchain_spent_txid, 'created_at', created_at, 'updated_at', updated_at, 'lightning_htlc_subscription_id', lightning_htlc_subscription_id)), '[]'::jsonb) AS rows FROM public.vtxo),
expiry_entitlement_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'vtxo_id', vtxo_id, 'gross_sat', gross_sat, 'irreversible_facts', irreversible_facts, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_entitlement),
expiry_allocation_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'expiry_height', expiry_height, 'generation', generation, 'status', status, 'sweep_txid', sweep_txid, 'sweep_tx', sweep_tx, 'broadcast_at', broadcast_at, 'confirmed_height', confirmed_height, 'confirmed_hash', confirmed_hash, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_allocation),
expiry_allocation_input_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('allocation_id', allocation_id, 'vtxo_id', vtxo_id)), '[]'::jsonb) AS rows FROM public.expiry_allocation_input),
expiry_allocation_coin_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('allocation_id', allocation_id, 'entitlement_id', entitlement_id, 'owner_mailbox', owner_mailbox, 'user_pubkey', user_pubkey, 'spk', spk, 'disposition', disposition, 'gross_sat', gross_sat, 'fee_sat', fee_sat, 'payout_sat', payout_sat, 'forfeited_sat', forfeited_sat, 'active', active, 'evidence', evidence)), '[]'::jsonb) AS rows FROM public.expiry_allocation_coin),
expiry_allocation_payout_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('allocation_id', allocation_id, 'output_index', output_index, 'spk', spk, 'amount_sat', amount_sat)), '[]'::jsonb) AS rows FROM public.expiry_allocation_payout),
expiry_fee_child_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'allocation_id', allocation_id, 'txid', txid, 'raw_tx', raw_tx, 'fee_sat', fee_sat, 'operator_remainder_sat', operator_remainder_sat, 'confirmed_height', confirmed_height, 'confirmed_hash', confirmed_hash, 'funding_kind', funding_kind, 'operator_net_contribution_sat', operator_net_contribution_sat, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_fee_child),
expiry_terminal_claim_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('entitlement_id', entitlement_id, 'txid', txid, 'height', height, 'hash', hash)), '[]'::jsonb) AS rows FROM public.expiry_terminal_claim),
user_exit_claim_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'raw_tx', raw_tx, 'confirmed_height', confirmed_height)), '[]'::jsonb) AS rows FROM public.user_exit_claim),
fallback_record_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'mailbox_pk', mailbox_pk, 'spk', spk, 'account_xpub', account_xpub, 'account_pubkey', account_pubkey, 'account_chain_code', account_chain_code, 'mailbox_sig', mailbox_sig, 'account_sig', account_sig, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.fallback_record),
expiry_owner_key_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_pubkey', user_pubkey, 'mailbox_pk', mailbox_pk, 'child_index', child_index)), '[]'::jsonb) AS rows FROM public.expiry_owner_key),
expiry_chain_view_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'generation', generation, 'invalid', invalid, 'invalid_from', invalid_from, 'rebuilt_captaind_height', rebuilt_captaind_height, 'rebuilt_captaind_hash', rebuilt_captaind_hash, 'rebuilt_watchmand_height', rebuilt_watchmand_height, 'rebuilt_watchmand_hash', rebuilt_watchmand_hash, 'rebuilt_ledger_count', rebuilt_ledger_count, 'rebuilt_ledger_revision', rebuilt_ledger_revision)), '[]'::jsonb) AS rows FROM public.expiry_chain_view),
expiry_sync_ack_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('process', process, 'generation', generation, 'height', height, 'hash', hash)), '[]'::jsonb) AS rows FROM public.expiry_sync_ack),
expiry_split_request_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('vtxo_id', vtxo_id, 'progress_txid', progress_txid, 'generation', generation, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_split_request),
lightning_node_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'pubkey', pubkey)), '[]'::jsonb) AS rows FROM public.lightning_node),
lightning_payment_attempt_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'lightning_node_id', lightning_node_id, 'amount_msat', amount_msat, 'status', status, 'created_at', created_at, 'updated_at', updated_at, 'payment_hash', payment_hash, 'final_amount_msat', final_amount_msat, 'sender_mailbox_id', sender_mailbox_id, 'lightning_htlc_subscription_id', lightning_htlc_subscription_id, 'block_height', block_height, 'user_fee_sat', user_fee_sat, 'max_routing_fee_msat', max_routing_fee_msat)), '[]'::jsonb) AS rows FROM public.lightning_payment_attempt),
lightning_payment_attempt_htlc_vtxo_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('lightning_payment_attempt_id', lightning_payment_attempt_id, 'vtxo_id', vtxo_id)), '[]'::jsonb) AS rows FROM public.lightning_payment_attempt_htlc_vtxo),
expiry_lightning_dispatch_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'label', label, 'checked_at', checked_at, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_dispatch),
expiry_lightning_terminal_failure_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'created_index', created_index, 'updated_index', updated_index, 'jsonrpc_error_code', jsonrpc_error_code, 'supervised_manifest_sha256', supervised_manifest_sha256, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_terminal_failure),
expiry_lightning_rpc_rejection_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'code', code, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_rpc_rejection),
expiry_lightning_queued_attempt_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_queued_attempt),
expiry_lightning_external_success_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'created_index', created_index, 'updated_index', updated_index, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_external_success),
expiry_lightning_internal_funding_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'subscription_id', subscription_id, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_internal_funding),
expiry_lightning_receive_claim_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('source_vtxo_id', source_vtxo_id, 'subscription_id', subscription_id, 'payment_hash', payment_hash, 'output_vtxo_id', output_vtxo_id, 'materialized', materialized, 'created_at', created_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_receive_claim),
expiry_lightning_receive_replay_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('subscription_id', subscription_id, 'payment_hash', payment_hash, 'encoding_version', encoding_version, 'protocol_version', protocol_version, 'created_at', created_at, 'last_attempt_at', last_attempt_at, 'uncollected_at', uncollected_at)), '[]'::jsonb) AS rows FROM public.expiry_lightning_receive_replay),
lightning_htlc_subscription_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'payment_hash', payment_hash, 'status', status, 'created_at', created_at, 'updated_at', updated_at, 'receiver_mailbox_id', receiver_mailbox_id)), '[]'::jsonb) AS rows FROM public.lightning_htlc_subscription),
captaind_block_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('height', height, 'hash', hash)), '[]'::jsonb) AS rows FROM public.captaind_block),
watchmand_block_rows AS (SELECT COALESCE(jsonb_agg(jsonb_build_object('height', height, 'hash', hash)), '[]'::jsonb) AS rows FROM public.watchmand_block)
SELECT jsonb_build_object(
  'transaction_read_only', current_setting('transaction_read_only'),
  'isolation', current_setting('transaction_isolation'),
  'snapshot', pg_current_snapshot()::text,
  'captured_at', transaction_timestamp(),
  'tables', jsonb_build_object(
    'vtxo', (SELECT rows FROM vtxo_rows),
    'expiry_entitlement', (SELECT rows FROM expiry_entitlement_rows),
    'expiry_allocation', (SELECT rows FROM expiry_allocation_rows),
    'expiry_allocation_input', (SELECT rows FROM expiry_allocation_input_rows),
    'expiry_allocation_coin', (SELECT rows FROM expiry_allocation_coin_rows),
    'expiry_allocation_payout', (SELECT rows FROM expiry_allocation_payout_rows),
    'expiry_fee_child', (SELECT rows FROM expiry_fee_child_rows),
    'expiry_terminal_claim', (SELECT rows FROM expiry_terminal_claim_rows),
    'user_exit_claim', (SELECT rows FROM user_exit_claim_rows),
    'fallback_record', (SELECT rows FROM fallback_record_rows),
    'expiry_owner_key', (SELECT rows FROM expiry_owner_key_rows),
    'expiry_chain_view', (SELECT rows FROM expiry_chain_view_rows),
    'expiry_sync_ack', (SELECT rows FROM expiry_sync_ack_rows),
    'expiry_split_request', (SELECT rows FROM expiry_split_request_rows),
    'lightning_node', (SELECT rows FROM lightning_node_rows),
    'lightning_payment_attempt', (SELECT rows FROM lightning_payment_attempt_rows),
    'lightning_payment_attempt_htlc_vtxo', (SELECT rows FROM lightning_payment_attempt_htlc_vtxo_rows),
    'expiry_lightning_dispatch', (SELECT rows FROM expiry_lightning_dispatch_rows),
    'expiry_lightning_terminal_failure', (SELECT rows FROM expiry_lightning_terminal_failure_rows),
    'expiry_lightning_rpc_rejection', (SELECT rows FROM expiry_lightning_rpc_rejection_rows),
    'expiry_lightning_queued_attempt', (SELECT rows FROM expiry_lightning_queued_attempt_rows),
    'expiry_lightning_external_success', (SELECT rows FROM expiry_lightning_external_success_rows),
    'expiry_lightning_internal_funding', (SELECT rows FROM expiry_lightning_internal_funding_rows),
    'expiry_lightning_receive_claim', (SELECT rows FROM expiry_lightning_receive_claim_rows),
    'expiry_lightning_receive_replay', (SELECT rows FROM expiry_lightning_receive_replay_rows),
    'lightning_htlc_subscription', (SELECT rows FROM lightning_htlc_subscription_rows),
    'captaind_block', (SELECT rows FROM captaind_block_rows),
    'watchmand_block', (SELECT rows FROM watchmand_block_rows)),
  'counts', jsonb_build_object(
    'vtxo', (SELECT jsonb_array_length(rows) FROM vtxo_rows),
    'expiry_entitlement', (SELECT jsonb_array_length(rows) FROM expiry_entitlement_rows),
    'expiry_allocation', (SELECT jsonb_array_length(rows) FROM expiry_allocation_rows),
    'expiry_allocation_input', (SELECT jsonb_array_length(rows) FROM expiry_allocation_input_rows),
    'expiry_allocation_coin', (SELECT jsonb_array_length(rows) FROM expiry_allocation_coin_rows),
    'expiry_allocation_payout', (SELECT jsonb_array_length(rows) FROM expiry_allocation_payout_rows),
    'expiry_fee_child', (SELECT jsonb_array_length(rows) FROM expiry_fee_child_rows),
    'expiry_terminal_claim', (SELECT jsonb_array_length(rows) FROM expiry_terminal_claim_rows),
    'user_exit_claim', (SELECT jsonb_array_length(rows) FROM user_exit_claim_rows),
    'fallback_record', (SELECT jsonb_array_length(rows) FROM fallback_record_rows),
    'expiry_owner_key', (SELECT jsonb_array_length(rows) FROM expiry_owner_key_rows),
    'expiry_chain_view', (SELECT jsonb_array_length(rows) FROM expiry_chain_view_rows),
    'expiry_sync_ack', (SELECT jsonb_array_length(rows) FROM expiry_sync_ack_rows),
    'expiry_split_request', (SELECT jsonb_array_length(rows) FROM expiry_split_request_rows),
    'lightning_node', (SELECT jsonb_array_length(rows) FROM lightning_node_rows),
    'lightning_payment_attempt', (SELECT jsonb_array_length(rows) FROM lightning_payment_attempt_rows),
    'lightning_payment_attempt_htlc_vtxo', (SELECT jsonb_array_length(rows) FROM lightning_payment_attempt_htlc_vtxo_rows),
    'expiry_lightning_dispatch', (SELECT jsonb_array_length(rows) FROM expiry_lightning_dispatch_rows),
    'expiry_lightning_terminal_failure', (SELECT jsonb_array_length(rows) FROM expiry_lightning_terminal_failure_rows),
    'expiry_lightning_rpc_rejection', (SELECT jsonb_array_length(rows) FROM expiry_lightning_rpc_rejection_rows),
    'expiry_lightning_queued_attempt', (SELECT jsonb_array_length(rows) FROM expiry_lightning_queued_attempt_rows),
    'expiry_lightning_external_success', (SELECT jsonb_array_length(rows) FROM expiry_lightning_external_success_rows),
    'expiry_lightning_internal_funding', (SELECT jsonb_array_length(rows) FROM expiry_lightning_internal_funding_rows),
    'expiry_lightning_receive_claim', (SELECT jsonb_array_length(rows) FROM expiry_lightning_receive_claim_rows),
    'expiry_lightning_receive_replay', (SELECT jsonb_array_length(rows) FROM expiry_lightning_receive_replay_rows),
    'lightning_htlc_subscription', (SELECT jsonb_array_length(rows) FROM lightning_htlc_subscription_rows),
    'captaind_block', (SELECT jsonb_array_length(rows) FROM captaind_block_rows),
    'watchmand_block', (SELECT jsonb_array_length(rows) FROM watchmand_block_rows)));
